{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment & Fees — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--ink:#0f1720;--muted:#6b7280;--accent:#6b9f8b;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--ink);background:linear-gradient(180deg, #f7faf9 0%, var(--bg) 100%);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-weight:600}
    .brand{font-weight:700;color:var(--ink)}
    .hero{padding:44px 28px 28px;display:grid;gap:18px}
    .hero .kicker{color:var(--muted);font-size:13px}
    .hero h1{margin:0;font-size:28px}
    .lead{color:var(--muted);max-width:60ch}
    .controls{display:flex;gap:10px;flex-wrap:wrap}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;cursor:pointer;font-weight:600}
    .btn.secondary{background:transparent;color:var(--accent);border:1px solid var(--accent)}
    main{padding:0 28px 80px}
    .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(12,15,20,0.04);border:1px solid rgba(15,23,32,0.04)}
    .card h3{margin:0 0 8px}
    .muted{color:var(--muted);font-size:14px}
    .price{font-weight:700;font-size:20px;margin-top:8px}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    .policies{margin-top:28px;padding:18px;border-radius:10px;background:linear-gradient(180deg, rgba(107,159,139,0.05), rgba(250,250,250,0.02));border:1px solid rgba(107,159,139,0.06)}
    footer{padding:24px 28px;border-top:1px solid rgba(15,23,32,0.04);display:flex;justify-content:space-between;align-items:center}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
    .reveal--visible{opacity:1;transform:none}
    .try-btn{background:transparent;border:1px dashed var(--accent);padding:8px 12px;border-radius:10px;color:var(--accent);cursor:pointer}
    .modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(6,8,10,0.45);visibility:hidden;opacity:0;transition:opacity .2s ease,visibility .2s}
    .modal[aria-hidden="false"]{visibility:visible;opacity:1}
    .modal__panel{width:min(720px,94vw);background:var(--card);border-radius:12px;padding:20px;box-shadow:0 12px 40px rgba(2,6,10,0.2);max-height:86vh;overflow:auto}
    .modal__head{display:flex;justify-content:space-between;align-items:center}
    .exercise{display:grid;gap:12px;margin-top:12px}
    .circle{width:120px;height:120px;border-radius:50%;border:6px solid rgba(107,159,139,0.14);display:flex;align-items:center;justify-content:center;margin:8px auto}
    .circle .dot{width:24px;height:24px;border-radius:50%;background:var(--accent);transform:scale(1);transition:transform 600ms ease}
    textarea{width:100%;height:120px;padding:10px;border-radius:8px;border:1px solid rgba(15,23,32,0.06);font-size:15px}
    .small{font-size:13px;color:var(--muted)}
    @media (prefers-reduced-motion:reduce){
      .reveal{transition:none;opacity:1;transform:none}
      .circle .dot{transition:none}
    }
    /* background pattern reference */
    .hero{background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-position:right top;background-size:360px}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="approach.html">Approach</a>
      <a href="specialties.html">Specialties</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="kicker">Practical structure for ongoing therapy</div>
      <h1>Fees & membership options</h1>
      <p class="lead">I offer a few predictable ways to work together so planning feels simple. If cost is a worry, sliding scale spots are available—email {{EMAIL}} to discuss confidentially.</p>
      <div class="controls">
        <button class="btn" id="primaryCta">{{PRIMARY_CTA_LABEL}}</button>
        <button class="btn secondary" id="tryIt">Try a guided exercise</button>
        <a class="small muted" href="faq.html">Payment questions →</a>
      </div>
    </section>

    <section class="cards reveal" aria-label="Membership options">
      <div class="card">
        <h3>Foundation Track</h3>
        <div class="muted">For those starting focused weekly work</div>
        <div class="price">$160 / session</div>
        <div class="note">Standard 50–60 minute sessions. Includes brief secure check-ins between appointments.</div>
      </div>

      <div class="card">
        <h3>Continuity Circle</h3>
        <div class="muted">Preferred for steady, ongoing support</div>
        <div class="price">$130 / session (monthly plan)</div>
        <div class="note">Monthly membership of 4 sessions billed as a single payment. Priority scheduling and one 15-minute messaging check-in per week.</div>
      </div>

      <div class="card">
        <h3>Flex Care</h3>
        <div class="muted">Occasional sessions without commitment</div>
        <div class="price">$185 / session</div>
        <div class="note">Pay-as-you-go; good for periodic review or short-term goals.</div>
      </div>
    </section>

    <section class="card session-fees reveal">
      <h3>Single session & add-ons</h3>
      <p class="muted">50–60 minute psychotherapy session: listed per plan above. 25–30 minute brief visit: $95. Initial intake session (90 minutes) is $195.</p>
      <p class="note">Payment accepted by card or invoice. Sliding scale available for a small number of clients; priority is given to those with financial need. Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> to inquire.</p>
    </section>

    <section class="policies reveal">
      <h3>Confidentiality, boundaries, and safety</h3>
      <p class="small">Sessions are confidential within legal and ethical limits. I will explain what confidentiality includes and any limits (such as concerns about safety). If you are experiencing a crisis or are in danger, please contact local emergency services or go to the nearest emergency department. This practice does not provide emergency services.</p>
      <p class="small">Therapy is a collaborative process. I do not promise outcomes; instead we work together to clarify goals and try approaches that may help. If a different level of care would be more appropriate, I will discuss referrals.</p>
    </section>
  </main>

  <footer>
    <div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <div class="muted">{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </div>
    <div>
      <button class="btn" id="footerBook">Book a time</button>
    </div>
  </footer>

  <div class="modal" id="exerciseModal" role="dialog" aria-hidden="true" aria-labelledby="modalTitle">
    <div class="modal__panel">
      <div class="modal__head">
        <h2 id="modalTitle">Guided micro-practice</h2>
        <button id="closeModal" aria-label="Close">Close</button>
      </div>
      <p class="small">Choose a short practice to ground your attention. These are not therapy sessions; they are brief exercises you can try now.</p>

      <div style="display:flex;gap:8px;margin-top:12px">
        <button class="try-btn" data-type="breath">Breathing</button>
        <button class="try-btn" data-type="journal">Journaling</button>
        <button class="try-btn" data-type="intent">Intention</button>
      </div>

      <div class="exercise" id="exerciseArea" aria-live="polite" style="margin-top:12px"></div>
    </div>
  </div>

  <script>
    // Basic navigation CTAs
    document.getElementById('primaryCta').addEventListener('click',function(){window.location.href='{{PRIMARY_CTA_URL}}'});
    document.getElementById('footerBook').addEventListener('click',function(){window.location.href='book.html'});

    // Modal + guided exercises
    const modal = document.getElementById('exerciseModal');
    const area = document.getElementById('exerciseArea');
    function openModal(){modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
    function closeModal(){modal.setAttribute('aria-hidden','true');area.innerHTML='';document.body.style.overflow=''}
    document.getElementById('tryIt').addEventListener('click',openModal);
    document.getElementById('closeModal').addEventListener('click',closeModal);
    modal.addEventListener('click',function(e){if(e.target===modal)closeModal()});

    function buildBreathing(){
      area.innerHTML = '';
      const info = document.createElement('div');
      info.innerHTML = '<div class="small">Box breathing: 4s inhale • hold 4s • 4s exhale • hold 4s. Do 3 cycles.</div>';
      const circle = document.createElement('div'); circle.className='circle';
      const dot = document.createElement('div'); dot.className='dot'; circle.appendChild(dot);
      const ctr = document.createElement('div'); ctr.style.textAlign='center'; ctr.appendChild(circle);
      area.appendChild(info); area.appendChild(ctr);
      let step=0; const phases=['Inhale','Hold','Exhale','Hold'];
      const durations=[4000,4000,4000,4000]; let cycles=0;
      const label = document.createElement('div'); label.style.textAlign='center'; label.style.fontWeight='700'; label.style.marginTop='8px'; area.appendChild(label);
      let t = setInterval(()=>{
        label.textContent = phases[step] + ' — cycle ' + (cycles+1) + '/3';
        if(phases[step]==='Inhale'){dot.style.transform='scale(1.4)'}
        if(phases[step]==='Exhale'){dot.style.transform='scale(.6)'}
        step++;
        if(step>=phases.length){step=0;cycles++;}
        if(cycles>=3){clearInterval(t);label.textContent='Finished — take a gentle breath.'}
      },4000);
      // respect prefers-reduced-motion
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){dot.style.transform='none';clearInterval(t);label.textContent='Follow the text prompts slowly; skip animation.'}
    }

    function buildJournal(){
      area.innerHTML = '';
      const prompt = document.createElement('div'); prompt.className='small'; prompt.textContent='Write for 5 minutes: "Right now, I notice..."';
      const ta = document.createElement('textarea'); ta.placeholder='Start with "Right now, I notice..."';
      const done = document.createElement('button'); done.className='btn'; done.textContent='Finish';
      done.addEventListener('click',()=>{area.innerHTML='<div class="small">If helpful, you can keep this note or copy it somewhere private. Close when ready.</div>'});
      area.appendChild(prompt); area.appendChild(ta); area.appendChild(done);
    }

    function buildIntent(){
      area.innerHTML = '';
      const p = document.createElement('div'); p.className='small'; p.textContent='A short intention practice: choose one small, specific action for today.';
      const input = document.createElement('input'); input.type='text'; input.placeholder='e.g., I will phone one friend'; input.style.width='100%'; input.style.padding='10px'; input.style.border='1px solid rgba(15,23,32,0.06)'; input.style.borderRadius='8px';
      const save = document.createElement('button'); save.className='btn'; save.textContent='Lock this intention';
      save.addEventListener('click',()=>{area.innerHTML='<div class="small">Intention saved for now. If you want, copy it into a journal or set a reminder.</div>'});
      area.appendChild(p); area.appendChild(input); area.appendChild(save);
    }

    document.querySelectorAll('.try-btn[data-type]').forEach(btn=>{
      btn.addEventListener('click',function(){
        const type=this.getAttribute('data-type');
        if(type==='breath')buildBreathing();
        if(type==='journal')buildJournal();
        if(type==='intent')buildIntent();
      });
    });

    // Scroll reveal with prefers-reduced-motion support
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduce){els.forEach(e=>e.classList.add('reveal--visible'));return}
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal--visible');io.unobserve(entry.target)}},{threshold:0.12});
      els.forEach(e=>io.observe(e));
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>FAQ — Fees & Policies — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--ink:#072021;--muted:#54636b;--accent:#7aab96}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--ink);background:linear-gradient(180deg,#fbfdfc,#fff)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{margin:0 6px;color:var(--muted);text-decoration:none}
    main{padding:12px 24px 80px;max-width:900px;margin:0 auto}
    h1{margin-top:8px}
    .qa{margin-top:18px}
    details{background:#fff;border-radius:10px;padding:12px;border:1px solid rgba(7,32,33,0.06);margin-bottom:12px}
    summary{font-weight:700;cursor:pointer}
    .answer{color:var(--muted);margin-top:8px}
    .cta{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(90deg,#fff,#fbfbfb);padding:14px;border-radius:10px;border:1px solid rgba(7,32,33,0.04);margin-top:18px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;cursor:pointer}
    .muted{color:var(--muted);font-size:14px}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .5s ease,transform .5s ease}
    .reveal--visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Approach</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main>
    <h1>Frequently asked questions</h1>
    <p class="muted">Below are practical answers written with clarity and clinical care. If you don’t see what you need, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>

    <section class="qa reveal">
      <details>
        <summary>How do I pay and what methods are accepted?</summary>
        <div class="answer">Card payments and invoicing are accepted. Membership plans are billed monthly when selected. If you need a different arrangement, please mention it in a private message and we will discuss options.</div>
      </details>

      <details>
        <summary>Is telehealth available?</summary>
        <div class="answer">Yes—sessions over a secure, HIPAA-conscious platform are available for most clients. In-person availability is noted on the booking page for those local to {{CITY}}, {{STATE}}.</div>
      </details>

      <details>
        <summary>What if I need to cancel or reschedule?</summary>
        <div class="answer">Please notify me as early as possible. Cancellation policies vary by plan; membership agreements will include specific terms. If an emergency arises, reach out and we will work to reschedule fairly.</div>
      </details>

      <details>
        <summary>Do you provide documentation for insurance?</summary>
        <div class="answer">I can provide a superbill if you wish to seek out-of-network reimbursement from your insurer. Some documents may require additional time and a fee—please ask in advance.</div>
      </details>

      <details>
        <summary>How is confidentiality handled?</summary>
        <div class="answer">Sessions are confidential within legal and ethical limits. Information is only shared with consent except in situations such as imminent risk of harm, suspected abuse, or as otherwise required by law. I will always discuss these limits with you.</div>
      </details>

      <details>
        <summary>What should I do in a crisis?</summary>
        <div class="answer">If you are in immediate danger or need urgent medical help, contact local emergency services or go to the nearest emergency department. This practice is not an emergency service and cannot guarantee immediate responses outside scheduled sessions.</div>
      </details>

      <details>
        <summary>How long does therapy typically last?</summary>
        <div class="answer">The length of work varies based on your goals and needs. Some people find short-term, focused support is enough; others prefer ongoing, periodic work. We’ll discuss a plan that fits your priorities during early sessions.</div>
      </details>

    </section>

    <div class="cta reveal" role="region" aria-label="Next steps">
      <div>
        <div style="font-weight:700">Ready to begin?</div>
        <div class="muted">Schedule an intake or ask a question first.</div>
      </div>
      <div style="display:flex;gap:8px">
        <button class="btn" id="bookNow">Book a time</button>
        <button class="btn" id="tryExercise">Try a short practice</button>
      </div>
    </div>

  </main>

  <script>
    document.getElementById('bookNow').addEventListener('click',()=>location.href='book.html');

    // Lightweight modal reuse from other pages — open a simple exercise in a new window-like panel
    document.getElementById('tryExercise').addEventListener('click',()=>{
      // Create a small in-page modal
      const m = document.createElement('div'); m.style.position='fixed';m.style.inset='0';m.style.background='rgba(2,6,8,0.45)';m.style.display='flex';m.style.alignItems='center';m.style.justifyContent='center';m.id='tempModal';
      const panel = document.createElement('div'); panel.style.background='#fff';panel.style.padding='18px';panel.style.borderRadius='10px';panel.style.maxWidth='520px';panel.style.width='92%';
      panel.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center"><strong>Try a moment</strong><button id="closeX">Close</button></div><p class="muted">Choose breathing or a quick intention to bring focus.</p>';
      const b1 = document.createElement('button'); b1.className='btn'; b1.textContent='Breathing'; b1.style.marginRight='8px';
      const b2 = document.createElement('button'); b2.className='btn'; b2.textContent='Intention';
      panel.appendChild(b1);panel.appendChild(b2); m.appendChild(panel); document.body.appendChild(m);
      document.getElementById('closeX').addEventListener('click',()=>m.remove());
      b1.addEventListener('click',()=>{alert('Box breathing: 4s inhale, 4s hold, 4s exhale, 4s hold. Repeat 3 times.');});
      b2.addEventListener('click',()=>{const i=prompt('Write a single small intention for today:'); if(i)alert('Your intention: '+i)});
    });

    // Scroll reveal
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduce){els.forEach(e=>e.classList.add('reveal--visible'));return}
      const io = new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('reveal--visible');io.unobserve(en.target)}})},{threshold:0.12});
      els.forEach(e=>io.observe(e));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfdfa;--ink:#082425;--muted:#4f5d5b;--accent:#7db299}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    main{max-width:960px;margin:12px auto;padding:0 20px}
    .panel{background:#fff;padding:18px;border-radius:12px;border:1px solid rgba(6,12,10,0.04)}
    h1{margin-top:4px}
    form{display:grid;gap:12px;margin-top:12px}
    label{font-weight:700}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid rgba(6,12,10,0.06);font-size:15px}
    .row{display:flex;gap:12px}
    .small{font-size:13px;color:var(--muted)}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;border:0;cursor:pointer}
    .types{display:flex;gap:8px;flex-wrap:wrap}
    .type{border:1px solid rgba(6,12,10,0.06);padding:10px;border-radius:8px;cursor:pointer}
    .type.active{outline:2px solid rgba(125,178,153,0.18)}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .5s ease,transform .5s ease}
    .reveal--visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="panel reveal">
      <h1>Schedule a session</h1>
      <p class="small">Select a session type and share a few details. Booking here initiates scheduling — you will receive a confirmation by email.</p>

      <form id="bookingForm" autocomplete="off">
        <div>
          <label for="name">Full name</label>
          <input id="name" name="name" required />
        </div>

        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" required />
        </div>

        <div>
          <label>Session type</label>
          <div class="types" role="list">
            <div class="type active" data-type="intake" role="listitem">90 min intake — $195</div>
            <div class="type" data-type="standard" role="listitem">50–60 min — $160</div>
            <div class="type" data-type="brief" role="listitem">25–30 min brief — $95</div>
          </div>
        </div>

        <div>
          <label for="when">Preferred days / times</label>
          <input id="when" name="when" placeholder="e.g., Tuesdays morning, or weekday evenings" />
        </div>

        <div>
          <label for="note">Short note about goals (optional)</label>
          <textarea id="note" name="note" placeholder="A few words about what you'd like to focus on"></textarea>
        </div>

        <div class="row">
          <button class="btn" type="submit">Request booking</button>
          <button type="button" id="tryNow" class="btn" style="background:#fff;color:var(--accent);border:1px solid rgba(125,178,153,0.18)">Try a micro-practice</button>
        </div>

        <div class="small">By requesting a booking you agree to a brief intake conversation by email or phone. For urgent safety concerns call local emergency services—this practice is not an emergency service.</div>
      </form>
    </section>

    <section style="margin-top:14px" class="panel reveal">
      <h2 style="margin:0">What happens after you request a booking</h2>
      <ol class="small">
        <li>We will reply to schedule a mutually available time and confirm platform details.</li>
        <li>If you choose a membership plan we will outline billing and scheduling terms in writing.</li>
        <li>Any questions about confidentiality or documentation will be addressed before or during the first session.</li>
      </ol>
    </section>
  </main>

  <script>
    // session type selector
    document.querySelectorAll('.type').forEach(t=>{
      t.addEventListener('click',()=>{
        document.querySelectorAll('.type').forEach(x=>x.classList.remove('active'));
        t.classList.add('active');
      });
    });

    // simple booking handler — opens client email using mailto (no server)
    document.getElementById('bookingForm').addEventListener('submit',function(e){
      e.preventDefault();
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      const when = document.getElementById('when').value.trim();
      const note = document.getElementById('note').value.trim();
      const type = document.querySelector('.type.active').getAttribute('data-type');
      const subject = encodeURIComponent('Booking request from ' + name);
      const body = encodeURIComponent('Name: '+name+'%0AEmail: '+email+'%0APreferred: '+when+'%0ASession: '+type+'%0ANotes: '+note);
      const mailto = 'mailto:{{EMAIL}}?subject='+subject+'&body='+body;
